import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../redux/formSlice';

export default function StepTwo({ next, prev }) {
  const dispatch = useDispatch();
  const { password, confirmPassword } = useSelector((state) => state.form);

  const strength = password.length > 5 ? 'Strong' : 'Weak';

  return (
    <div>
      <input type="password" placeholder="Password" value={password} onChange={(e) => dispatch(updateField({ field: 'password', value: e.target.value }))} />
      <input type="password" placeholder="Confirm Password" value={confirmPassword} onChange={(e) => dispatch(updateField({ field: 'confirmPassword', value: e.target.value }))} />
      <p>Password Strength: {strength}</p>
      <button onClick={prev}>⬅ Prev</button>
      <button onClick={next}>Next ➜</button>
    </div>
  );
}
